Database Schema:
CREATE TABLE `Customers` (
  `Customer_ID` NUMBER,
  `Customer_name` TEXT,
  PRIMARY KEY (`Customer_ID`)
);

CREATE TABLE `Services` (
  `Service_ID` NUMBER,
  `Service_name` TEXT,
  PRIMARY KEY (`Service_ID`)
);

CREATE TABLE `Available_Policies` (
  `Policy_ID` NUMBER,
  `policy_type_code` TEXT,
  `Customer_Phone` TEXT,
  PRIMARY KEY (`Policy_ID`)
);

CREATE TABLE `Customers_Policies` (
  `Customer_ID` NUMBER REFERENCES `Customers`(`Customer_ID`),
  `Policy_ID` NUMBER REFERENCES `Available_Policies`(`Policy_ID`),
  `Date_Opened` TIME,
  `Date_Closed` TIME,
  PRIMARY KEY (`Customer_ID`)
);

CREATE TABLE `First_Notification_of_Loss` (
  `FNOL_ID` NUMBER,
  `Customer_ID` NUMBER REFERENCES `Customers_Policies`(`Customer_ID`),
  `Policy_ID` NUMBER REFERENCES `Customers_Policies`(`Policy_ID`),
  `Service_ID` NUMBER REFERENCES `Services`(`Service_ID`),
  PRIMARY KEY (`FNOL_ID`)
);

CREATE TABLE `Claims` (
  `Claim_ID` NUMBER,
  `FNOL_ID` NUMBER REFERENCES `First_Notification_of_Loss`(`FNOL_ID`),
  `Effective_Date` TIME,
  PRIMARY KEY (`Claim_ID`)
);

CREATE TABLE `Settlements` (
  `Settlement_ID` NUMBER,
  `Claim_ID` NUMBER REFERENCES `Claims`(`Claim_ID`),
  `Effective_Date` TIME,
  `Settlement_Amount` NUMBER,
  PRIMARY KEY (`Settlement_ID`)
);

